window.ScripturaLexicons.BDAG_PART_0230 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-01\" data-source=\"BDAG\" data-search=\"μέλι, ιτος, τό substantivo neutro mel; doçura; remédio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέλι, ιτος, τό</td><td>substantivo neutro</td><td>mel; doçura; remédio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-02\" data-source=\"BDAG\" data-search=\"μέλισσα, ης, ἡ substantivo feminino abelha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέλισσα, ης, ἡ</td><td>substantivo feminino</td><td>abelha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-03\" data-source=\"BDAG\" data-search=\"μελίσσιος, ιον adjetivo relativo à abelha; favo; colmeia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μελίσσιος, ιον</td><td>adjetivo</td><td>relativo à abelha; favo; colmeia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-04\" data-source=\"BDAG\" data-search=\"Μελίτη, ης, ἡ nome próprio feminino Malta; ilha do Mediterrâneo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μελίτη, ης, ἡ</td><td>nome próprio feminino</td><td>Malta; ilha do Mediterrâneo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-05\" data-source=\"BDAG\" data-search=\"Μελιτήνη remissão ver Μελίτη BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μελιτήνη</td><td>remissão</td><td>ver Μελίτη</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-06\" data-source=\"BDAG\" data-search=\"μέλλω verbo estar para; tencionar; estar destinado a; tardar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέλλω</td><td>verbo</td><td>estar para; tencionar; estar destinado a; tardar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-07\" data-source=\"BDAG\" data-search=\"μέλομαι verbo médio ser objeto de cuidado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέλομαι</td><td>verbo médio</td><td>ser objeto de cuidado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-08\" data-source=\"BDAG\" data-search=\"μέλος, ους, τό substantivo neutro membro corporal; integrante de um corpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέλος, ους, τό</td><td>substantivo neutro</td><td>membro corporal; integrante de um corpo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-09\" data-source=\"BDAG\" data-search=\"Μελχί, ὁ nome próprio masculino Melqui; ancestral de Jesus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μελχί, ὁ</td><td>nome próprio masculino</td><td>Melqui; ancestral de Jesus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-10\" data-source=\"BDAG\" data-search=\"Μελχισέδεκ, ὁ nome próprio masculino Melquisedeque; sacerdote e rei de Salém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μελχισέδεκ, ὁ</td><td>nome próprio masculino</td><td>Melquisedeque; sacerdote e rei de Salém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-11\" data-source=\"BDAG\" data-search=\"μέλω remissão ver μέλομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέλω</td><td>remissão</td><td>ver μέλομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-12\" data-source=\"BDAG\" data-search=\"μεμβράνα, ης, ἡ substantivo feminino pergaminho; rolos; códices BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεμβράνα, ης, ἡ</td><td>substantivo feminino</td><td>pergaminho; rolos; códices</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-13\" data-source=\"BDAG\" data-search=\"μεμενήκεισαν remissão ver μένω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεμενήκεισαν</td><td>remissão</td><td>ver μένω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-14\" data-source=\"BDAG\" data-search=\"μέμιγμαι remissão ver μίγνυμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέμιγμαι</td><td>remissão</td><td>ver μίγνυμι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-15\" data-source=\"BDAG\" data-search=\"μεμμίαμαι remissão ver μιαίνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεμμίαμαι</td><td>remissão</td><td>ver μιαίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-16\" data-source=\"BDAG\" data-search=\"μέμνημαι remissão ver μιμνῄσκομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέμνημαι</td><td>remissão</td><td>ver μιμνῄσκομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-17\" data-source=\"BDAG\" data-search=\"μέμφομαι verbo censurar; repreender; culpar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέμφομαι</td><td>verbo</td><td>censurar; repreender; culpar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-18\" data-source=\"BDAG\" data-search=\"μεμψίμοιρος, ον adjetivo queixoso da própria sorte; descontente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεμψίμοιρος, ον</td><td>adjetivo</td><td>queixoso da própria sorte; descontente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-19\" data-source=\"BDAG\" data-search=\"μέμψις, εως, ἡ substantivo feminino motivo de queixa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέμψις, εως, ἡ</td><td>substantivo feminino</td><td>motivo de queixa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0230-20\" data-source=\"BDAG\" data-search=\"μέν partícula partícula correlativa; concessão; contraste; continuação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέν</td><td>partícula</td><td>partícula correlativa; concessão; contraste; continuação</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0230-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλι, ιτος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέλι</span>, <span class=\"greek\">ιτος</span>, <span class=\"greek\">τό</span> (Hom. e posteriores), mel; doce <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:9</a>s. (Ezk 3:3); Hm 5, 1, 5s. Com leite, como alimento para crianças (Diod S 5, 70, 3; Philostrat., Her. 19, 19; Is 7:15, 22) 6:17; sinal de fertilidade (escólio a Pind., O. 1, 157c [98] <span class=\"greek\">γῆ</span> <span class=\"greek\">μέλι</span> <span class=\"greek\">ῥέουσα</span>) 6:8, 10, 13 (Ex 33:3; sobre a fórmula, ver HUsener [ver <span class=\"greek\">γάλα</span> b]; NDahl, MGoguel Festschr. ’50, 62–70). <span class=\"greek\">μ</span>. <span class=\"greek\">ἄγριον</span> (ver <span class=\"greek\">ἄγριος</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:6</a>; GEb13, 79 (na Antiguidade, <span class=\"greek\">μ</span>. era frequentemente associado à inspiração divina e à expressão oracular; cf. Pind., P. 4, 60 e o escólio correspondente).—Como remédio curativo, <span class=\"greek\">μέλιτι</span> <span class=\"greek\">θεράπευε</span> <span class=\"greek\">σεαυτόν</span> AcPl Ha 5, 36. SKrauss, Honig in Palästina: ZDPV 32, 1909, 151–64; Dalman, Arbeit VII (ver <span class=\"greek\">οἰκία</span> 1a).—AMayor, Mad Honey!: Archaeology 48/6, 32–40 (informativo, mas sem documentação detalhada das fontes antigas); BHHW II 747.—B. 384. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλισσα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέλισσα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">μέλι</span>; Hom. e outros; PSI 426, 13; Ps.-Phoc. 127; JosAs; Philo em Eus., PE. 8, 11, 8; Jos., Ant. 5, 288; 6, 118), abelha 6:6 (Ps 117:12).—B. 192. DELG s.v. <span class=\"greek\">μέλι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μελίσσιος, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μελίσσιος</span>, <span class=\"greek\">ιον</span> (ver verbete precedente), relativo à abelha (Syntipas p. 28, 9; 29, 3); <span class=\"greek\">μελίσσιον</span> <span class=\"greek\">κηρίον</span>, favo de mel (das abelhas) (Biogr. p. 93; Syntipas 28, 7); <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μελισσίου</span> <span class=\"greek\">κηρίου</span>, um pouco de favo de mel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:42</a>, variante textual. Substantivado: <span class=\"greek\">τὸ</span> <span class=\"greek\">μελίσς</span>(<span class=\"greek\">ε</span>)<span class=\"greek\">ιον</span>, colmeia (ApcSed 8, 5 p. 132, 38 Ja. [“abelha”]; PCairZen 467 [século III a.C.]; escólio a Nicander, Alexiph. 547; Hesych.); <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μελισσίου</span> <span class=\"greek\">κήριον</span>, um favo de mel de uma colmeia v. 42, variante textual.—EbNestle, ZDPV 30, 1907, 209s.; EGrafvMülinen, ibid. 35, 1912, 105ss.; LKöhler, ibid. 54, ’31, 289ss.; GDalman, ibid. 55, ’32, 80s.; PKatz, TLZ 83, ’58, 315. DELG s.v. <span class=\"greek\">μέλι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μελίτη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μελίτη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span>, Malta, ilha situada ao sul da Sicília (M. está atestado como nome dessa ilha em Diod S 15, 12, 2; Strabo 6, 2, 11; 17, 3, 16; Ps.-Scylax 94 [p. 37 BFabricius 1878]; inscrições) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:1</a>.—Sobre o debate acerca da identificação com Mijet, ao largo da costa dálmata (entre os primeiros na época moderna, AAcworth, JTS 24, ’73, 190–93), e com Cefalênia (Warnecke, Romfahrt 59–69; 145–56), ver BRapske, BAFCS II 36–43.—AMayr, D. Insel Malta im Altertum 1909; Zahn, AG 841–44; JvonFreeden, Malta u. die Baukunst seiner Megalith-Tempel ’93; Pauly-W. XV 543ss.; Kl. Pauly III 1179; DAC X 1320ss.; BHHW II 1132s.; OEANE III 402–5.—Boffo, Iscrizioni n.º 22. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μελιτήνη</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μελιτήνη</span>, variante textual de <span class=\"greek\">Μελίτη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέλλω</span> (Hom. e posteriores), futuro <span class=\"greek\">μελλήσω</span>; imperfeito <span class=\"greek\">ἔμελλον</span> (todas as edições <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:27</a>) e <span class=\"greek\">ἤμελλον</span> (todas as edições <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:2</a>; 19:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:47</a>; 12:33; 18:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>; ver B-D-F §66, 3; W.-S. §12, 3; Mlt-H. 188. Nas inscrições áticas, a forma com <span class=\"greek\">ἠ</span>- aparece depois de 300 a.C. [Meisterhans3-Schw. 169]. Em IPriene, a forma com <span class=\"greek\">ἐ</span>- ocorre apenas uma vez: 11, 5 [cerca de 297 a.C.]).</p><p class=\"entry-text\">① Acontecer em algum momento futuro e, portanto, ser posterior a outro acontecimento: estar para, estar prestes a, com um infinitivo subsequente.</p><p class=\"entry-text\">ⓐ Apenas raramente com infinitivo futuro, com o qual é regularmente empregado no grego antigo (Hom. e outros), uma vez que, no uso coloquial, o infinitivo e o particípio futuros desapareciam gradualmente e eram substituídos por construções com <span class=\"greek\">μέλλω</span> (B-D-F §338, 3; 350; ver Rob. 882; 889). Com o infinitivo futuro, <span class=\"greek\">μ</span>. denota a certeza de que algo ocorrerá futuramente: <span class=\"greek\">μ</span>. <span class=\"greek\">ἔσεσθαι</span> (SIG 914, 10 <span class=\"greek\">μέλλει</span> <span class=\"greek\">ἔσεσθαι</span>; 247 I, 74 <span class=\"greek\">ἔμελλε</span> … [<span class=\"greek\">δώσε</span>]<span class=\"greek\">ιν</span>; Jos., Ant. 13, 322; Mel., P. 57, 415), certamente acontecerá ou existirá <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a>; 24:15; 27:10; 1 Cl 43:6; cf. Dg 8:2.</p><p class=\"entry-text\">ⓑ Com infinitivo aoristo (raro no grego antigo [mas já em Hom., e, por exemplo, X., Cyr. 1, 4, 16]; Herodas 3, 78 e 91; UPZ 70, 12 [152/1 a.C.]; PGiss 12, 5; POxy 1067, 17; 1488, 20; Ex 4:12; Job 3:8; 2 Macc 14:41; JosAs 29:3; ParJer 9:13; GrBar 4:15 [cristão]; ApcMos13; ver Phryn. p. 336; 745ss. Lob.; WRutherford, New Phryn. 1881, 420ss.), estar a ponto de, estar prestes a: <span class=\"greek\">μ</span>. <span class=\"greek\">ἀποκαλυφθῆναι</span>, estar prestes a ser revelado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:18</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">δωδεκάφυλον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραὴλ</span> <span class=\"greek\">μέλλον</span> <span class=\"greek\">ἀπολέσθαι</span>, as doze tribos de Israel que estavam prestes a ser destruídas 1 Cl 55:6. <span class=\"greek\">ἤμελλεν</span> <span class=\"greek\">προαγαγεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:6</a>. <span class=\"greek\">ἀποθανεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:2</a>. <span class=\"greek\">ἐμέσαι</span> v. 16. <span class=\"greek\">τεκεῖν</span> 12:4.</p><p class=\"entry-text\">ⓒ Com infinitivo presente. É o uso predominante (cerca de 80 ocorrências no NT; frequente na literatura, inscrições, papiros, LXX; TestAbr B 4 p. 108, 14 [Stone p. 64]; ApcEsdr 6:23s. p. 32, 2s. Tdf.; EpArist; Demetr.: 722 Fgm. 7 Jac.; Just., A I, 51, 8; D. 32, 4 e outros; Tat. 14, 1; Mel., P. 38, 263; Ath. 32, 1).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Estar prestes a, estar a ponto de: <span class=\"greek\">ἤμελλεν</span> <span class=\"greek\">τελευτᾶν</span>, ele estava à beira da morte (Aristot. Fgm. 277 [em Apollon. Paradox. 27] e Diod S 6, 4, 3 <span class=\"greek\">μέλλων</span> <span class=\"greek\">τελευτᾶν</span>; cf. Jos., Ant. 4, 83; 12, 357) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:2</a>. Também <span class=\"greek\">ἤμελλεν</span> <span class=\"greek\">ἀποθνῄσκειν</span> (Artem. 4, 24 p. 217, 5 <span class=\"greek\">γραῦς</span> <span class=\"greek\">μέλλουσα</span> <span class=\"greek\">ἀποθνῄσκειν</span>; Aesop, Fab. 131 P.=202 H.; 233 P.=216 H.; 2 Macc 7:18; 4 Macc 10:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:47</a>. <span class=\"greek\">ἤμελλεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἀναιρεῖν</span>, ele estava prestes a matar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:27</a>. Sobre o reinado escatológico de Deus, <span class=\"greek\">μέλλειν</span> <span class=\"greek\">ἔρχεσθαι</span> 1 Cl 42:3. Sobre a glória celestial, <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span> <span class=\"greek\">ἀποκαλύπτεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:1</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:3</a>; 5:35; 18:14; 21:27; 22:26; 23:27.—Ocasionalmente, quase equivale a começar: <span class=\"greek\">ἤμελλον</span> <span class=\"greek\">γράφειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:4</a>. <span class=\"greek\">ὅταν</span> <span class=\"greek\">μέλλῃ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">συντελεῖσθαι</span> <span class=\"greek\">πάντα</span>, quando todas essas coisas estiverem prestes a cumprir-se (ou começarem a cumprir-se) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:4</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:7</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em sentido enfraquecido, funciona simplesmente como perífrase do futuro (PMich III, 202, 8ss.; 13ss. [105 d.C.].—Mayser II/1, 226): <span class=\"greek\">ὅσα</span> <span class=\"greek\">λαλῶ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">λαλεῖν</span> (=<span class=\"greek\">ἢ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λαλήσω</span>), o que digo ou direi Hm 4, 4, 3. Assim, especialmente frequente em Hermas: <span class=\"greek\">μ</span>. <span class=\"greek\">λέγειν</span> v 1, 1, 6; 3, 8, 11; m 11:7, 17; Hs 5, 2, 1. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐντέλλεσθαι</span> v 5:5; m 5, 2, 8. <span class=\"greek\">μ</span>. <span class=\"greek\">κατοικεῖν</span> Hs 1:1; 4:2. <span class=\"greek\">μ</span>. <span class=\"greek\">χωρεῖν</span> (=<span class=\"greek\">χωρήσω</span>) IMg 5:1. <span class=\"greek\">μ</span>. <span class=\"greek\">βασιλεύειν</span> GJs 23:2.—Substitui formas futuras em desaparecimento (infinitivo e particípio, B-D-F §356): no lugar do infinitivo futuro, <span class=\"greek\">προσεδόκων</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">μέλλειν</span> <span class=\"greek\">πίμπρασθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:6</a>; no lugar do particípio futuro, <span class=\"greek\">ὁ</span> <span class=\"greek\">μέλλων</span> <span class=\"greek\">ἔρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:14</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">μέλλων</span> <span class=\"greek\">πράσσειν</span>, aquele que estava para fazer isto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:23</a>; cf. 24:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:34</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">μέλλοντες</span> <span class=\"greek\">πιστεύειν</span>, os que haveriam de crer (nele) futuramente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:16</a>; 1 Cl 42:4; Hm 4, 3, 3. <span class=\"greek\">μέλλοντες</span> <span class=\"greek\">ἀσεβεῖν</span>, os que haveriam de agir impiamente no futuro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:6</a>, variante textual (ver 3, final). Sobre Cristo, <span class=\"greek\">ὁ</span> <span class=\"greek\">μέλλων</span> <span class=\"greek\">κρίνειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:1</a>; 7:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">μέλλοντες</span> <span class=\"greek\">ἀρνεῖσθαι</span> = <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀρνησόμενοι</span> Hv 2, 2, 8. <span class=\"greek\">πυρὸς</span> <span class=\"greek\">ζῆλος</span> <span class=\"greek\">ἐσθίειν</span> <span class=\"greek\">μέλλοντος</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὑπεναντίους</span>, fogo ardente que devorará os adversários <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:27</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Indica uma ação pretendida: tencionar, propor-se, ter em mente: <span class=\"greek\">μέλλει</span> <span class=\"greek\">Ἡρῴδης</span> <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παιδίον</span>, Herodes tenciona procurar o menino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:13</a>. <span class=\"greek\">οὗ</span> <span class=\"greek\">ἤμελλεν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἔρχεσθαι</span>, onde ele próprio tencionava ir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:1</a>. <span class=\"greek\">μέλλουσιν</span> <span class=\"greek\">ἔρχεσθαι</span>, eles tencionavam vir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:15</a>. Cf. v. 71; 7:35; 12:4; 14:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:31</a>; 20:3, 7, 13ab; 23:15; 26:2; 27:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:12</a>. <span class=\"greek\">τί</span> <span class=\"greek\">μέλλεις</span> <span class=\"greek\">ποιεῖν</span>;, que pretendes fazer? Hs 1:5. <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ποιεῖν</span>, não tenho intenção de fazer MPol 8:2. <span class=\"greek\">μ</span>. <span class=\"greek\">προσηλοῦν</span>, queriam pregá-lo com pregos 13:3. <span class=\"greek\">μ</span>. <span class=\"greek\">λαμβάνειν</span>, queríamos retirá-lo 17:2.</p><p class=\"entry-text\">② Ser inevitável, estar destinado a acontecer: inevitável.</p><p class=\"entry-text\">ⓐ Com infinitivo presente, para indicar uma ação que decorre necessariamente de um decreto divino: estar destinado a, dever, certamente haver de …: <span class=\"greek\">μ</span>. <span class=\"greek\">πάσχειν</span>, está destinado a sofrer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a>; B 7:10; 12:2; cf. 6:7. <span class=\"greek\">μ</span>. <span class=\"greek\">σταυροῦσθαι</span>, deve ser crucificado 12:1. <span class=\"greek\">μ</span>. <span class=\"greek\">παραδίδοσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:44</a>; 16:5. <span class=\"greek\">ἔμελλεν</span> <span class=\"greek\">ἀποθνῄσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:51</a>; 12:33; 18:32. <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">φανεροῦσθαι</span> B 6:7, 9, 14. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:27</a>; 20:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:24</a>; 8:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:5</a>. <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">μέλλουσιν</span> … <span class=\"greek\">θεωρεῖν</span>, já não haveriam de ver … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:38</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">γίνεσθαι</span>, aquilo que necessariamente há de acontecer 26:22; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:19</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μέλλοντας</span> <span class=\"greek\">κληρονομεῖν</span> <span class=\"greek\">σωτηρίαν</span>, por causa dos que hão de herdar a salvação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:14</a>. <span class=\"greek\">μέλλομεν</span> <span class=\"greek\">θλίβεσθαι</span>, que estávamos destinados a ser afligidos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:4</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἔμελλε</span> <span class=\"greek\">θηριομαχεῖν</span>, no dia em que Paulo haveria de combater feras AcPl Ha 3, 9. <span class=\"greek\">ὡς</span> <span class=\"greek\">μελλούσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">αἴρεσθαι</span>, na expectativa da destruição da cidade 5, 16. <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">μέλλω</span> <span class=\"greek\">σταυροῦσθαι</span>, eu (Jesus) estou prestes a ser crucificado novamente 7, 39.</p><p class=\"entry-text\">ⓑ Com infinitivo aoristo, <span class=\"greek\">ἀποκαλυφθῆναι</span>, aquilo que está destinado (segundo a vontade de Deus) a ser revelado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:23</a>.</p><p class=\"entry-text\">③ O particípio é empregado de modo absoluto no sentido de (no) futuro, por vir (Pind., O. 10, 7 <span class=\"greek\">ὁ</span> <span class=\"greek\">μέλλων</span> <span class=\"greek\">χρόνος</span>, “a data devida”): <span class=\"greek\">ὁ</span> <span class=\"greek\">αἰὼν</span> <span class=\"greek\">μέλλων</span>, a era vindoura (ver <span class=\"greek\">αἰών</span> 2b), que traz o reinado de Deus (em oposição a <span class=\"greek\">ὁ</span> <span class=\"greek\">αἰὼν</span> <span class=\"greek\">οὗτος</span> ou <span class=\"greek\">ὁ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">αἰών</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:21</a>; 2 Cl 6:3; Pol 5:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:5</a>. Também <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">καιρός</span> (oposto a <span class=\"greek\">ὁ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">κ</span>.) 4:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ζωή</span> (oposto a <span class=\"greek\">ἡ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ζ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:8</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">βίος</span> (oposto a <span class=\"greek\">ὁ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">β</span>.) 2 Cl 20:2. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">βασιλεία</span> 5:5; <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκουμένη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>., o mundo vindouro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:5</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span> <span class=\"greek\">πόλις</span> (como jogo de palavras, em oposição a [<span class=\"greek\">οὐ</span> … ] <span class=\"greek\">μένουσα</span> <span class=\"greek\">π</span>.) 13:14. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπαγγελία</span>, a promessa para o futuro 2 Cl 10:3s. <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀγαθά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:11</a>, variante textual; Hv 1, 1, 8. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀνάστασις</span> 1 Cl 24:1; <span class=\"greek\">τὸ</span> <span class=\"greek\">κρίμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>., o juízo vindouro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:25</a>; cf. 1 Cl 28:1; 2 Cl 18:2; MPol 11:2. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὀργή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a>; IEph 11:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θλῖψις</span> Hv 4, 2, 5. <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σκάνδαλα</span> 4:9.—<span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἀδελφή</span>, tua futura irmã = aquela que no futuro será tua irmã, não mais tua esposa Hv 2, 2, 3. Por diversas vezes, um substantivo pode ser suprido pelo contexto: <span class=\"greek\">τύπος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μέλλοντος</span>, isto é, <span class=\"greek\">Ἀδάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:14</a>.—Substantivado, <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλλον</span>, o futuro (Aeneas Tact. 422; 431 e outros; Antiphanes Com. [século IV a.C.] 227 K.; Menand., Monostich. 412 [608 Jaekel] Mei.; Anacreont. 36; Plut., Caes. 14, 4; Herodian 1, 14, 2; SIG 609, 5; ViEzk 13 [p. 75, 12 Sch.]; Philo, Mel.) 1 Cl 31:3. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>., para o futuro (Jos., Ant. 9, 162) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:19</a>; especificamente, (no) próximo ano (PLond III, 1231, 4 p. 108 [144 d.C.] <span class=\"greek\">τὴν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλλον</span> <span class=\"greek\">γεωργείαν</span>; ver Field, Notes 65) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:9</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>., as coisas vindouras (X., Symp. 4, 47; Aeneas Tact. 1050; Artem. 1, 36; Wsd 19:1; TestJob 47:9; JosAs 23:8; Philo; Just., D. 7, 1; Ath. 27, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:17</a>; PtK 3 p. 15, 21. (Em oposição a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνεστῶτα</span>, o presente, como em PGM 5, 295) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:22</a>; B 1:7; 5:3; 17:2. Ox 1081 39s. (SJCh 91, 2) (ver <span class=\"greek\">ἀρχή</span> 2). Incerto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:6</a> (se <span class=\"greek\">ἀσεβέσιν</span> for mantido, a referência é ao juízo iminente dos ímpios).</p><p class=\"entry-text\">④ Demorar, tardar: <span class=\"greek\">τί</span> <span class=\"greek\">μέλλεις</span>, por que tardas? (cf. Aeschyl., Prom. 36; Eur., Hec. 1094; Thu. 8, 78; Lucian, Dial. Mort. 10, 13; Jos., Bell. 3, 494 <span class=\"greek\">τί</span> <span class=\"greek\">μέλλομεν</span>; 4 Macc 6:23; 9:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:16</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">μελλήσας</span>, sem demora AcPl Ha 8, 4. A conexão em AcPt Ox 849, 1 é incerta.—B. 974. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέλομαι</span> (cf. <span class=\"greek\">μέλει</span>; forma média em Hom., Od. 10, 505, e também em papiros), ser objeto de cuidado, constituir motivo de preocupação: <span class=\"greek\">μεμελημένη</span> <span class=\"greek\">θεῷ</span>, tu (Maria), por quem Deus demonstra cuidado e solicitude GJs 13:2 (<span class=\"greek\">γενέθλη</span> <span class=\"greek\">χρυσείη</span> … <span class=\"greek\">θεῷ</span> <span class=\"greek\">μεμελημένη</span> <span class=\"greek\">ἔσται</span> SibOr 1, 286.—Quanto ao sentido, cf. <span class=\"greek\">ἄνθρωπε</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μεμελετημένε</span> TestAbr B 2 p. 106, 19 [Stone p. 60]). Ver deStrycker p. 307.—DELG s.v. <span class=\"greek\">μέλι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέλος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e posteriores).</p><p class=\"entry-text\">① Parte do corpo humano: membro, parte, extremidade, literalmente, acerca de partes do corpo humano (cf. Did., Gen. 8 A, 7); <span class=\"greek\">καθάπερ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἔχομεν</span>, assim como temos muitas partes/membros num só corpo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:4a</a>b; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:12a</a>, 14, 18–20, 25s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:5</a> (Apollod. [século II a.C.]: 244 Fgm. 307 Jac. <span class=\"greek\">κράτιστον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μελῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γλῶσσα</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>, as partes do corpo (Diod S 5, 18, 12; Philo, In Flacc. 176; Orig., C. Cels. 7, 38, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:12b</a>, 22; 1 Cl 37:5; Dg 6:2. Com <span class=\"greek\">σάρξ</span> 6:6. <span class=\"greek\">μ</span>. <span class=\"greek\">σκοτεινόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:36</a>, variante textual. Com genitivo pessoal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:29</a>s. (cf. Sextus 13); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:13a</a>b; 19ab; 7:5, 23ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:6</a>; 4:1 (o plural nessas passagens também poderia referir-se ao “corpo” como soma de suas partes; entretanto, o plural <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> em Pind., N. 11, 15, invocado para sustentar essa interpretação, não significa o corpo como tal, mas é empregado pateticamente em referência aos membros do atleta, tão essenciais à sua profissão, como <span class=\"greek\">θνατά</span>, isto é, mesmo em pleno vigor, o atleta deve reconhecer sua mortalidade). <span class=\"greek\">συγκοπὴ</span> <span class=\"greek\">μελῶν</span>, mutilação dos membros (que conduz ao martírio; Diod S 17, 83, 9 descreve um procedimento desse tipo) IRo 5:3.—Metaforicamente, a respeito de características ou condutas pecaminosas: <span class=\"greek\">νεκρώσατε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, mortificai vossos membros terrenos = mortificai tudo em vós que é mundano <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:5</a>.</p><p class=\"entry-text\">② Parte enquanto integrante de um todo: membro, extensão figurada da acepção 1; acerca do organismo multifacetado da comunidade cristã (sobre a figura do corpo e de seus membros, recorrente na literatura antiga, por exemplo Aristot., Pol. 1253a 20–29; cf. Ar. 13, 5; Ath. 8, 1; ver Ltzm., Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:12</a>; WNestle, D. Fabel des Menenius Agrippa: Klio 21, 1927, 350–60): os cristãos individualmente são membros de Cristo e, em conjunto, constituem seu corpo (quanto a essa ideia, cf. Simplicius em Epict. p. 70, 51: as almas são <span class=\"greek\">μέρη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; 71, 5.—Na p. 80, 54 a alma é chamada <span class=\"greek\">μέρος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μέλος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; Iren. 5, 2, 2 [Harv. II 319, 2, 1]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:30</a>; 1 Cl 46:7; IEph 4:2; ITr 11:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:16</a>, variante textual. <span class=\"greek\">ἀλλήλων</span> <span class=\"greek\">μέλη</span>, membros uns dos outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:25</a>; 1 Cl 46:7b. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:15a</a>, por um motivo especial, os <span class=\"greek\">σώματα</span> dos cristãos são chamados <span class=\"greek\">μέλη</span> <span class=\"greek\">Χριστοῦ</span>. Uma vez que, segundo o entendimento de Paulo acerca de Gen 2:24, o ato sexual significa a união dos corpos (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:16</a>), as relações com uma prostituta tornam-se, desse ponto de vista, particularmente repugnantes v. 15b.—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μελχί, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μελχί</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">מַלְכִּי</span>), Melqui, na genealogia de Jesus (AssMos Fgm. c).</p><p class=\"entry-text\">① Filho de Janai, pai de Levi <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:24</a>.</p><p class=\"entry-text\">② Filho de Adi, pai de Neri v. 28.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μελχισέδεκ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μελχισέδεκ</span>, <span class=\"greek\">ὁ</span>, também -<span class=\"greek\">σεδέκ</span>; indeclinável (<span class=\"hebrew\" dir=\"rtl\">מַלְכִּי־צֶדֶק</span>; Gen 14:18; Philo, Leg. All. 3, 79; Jos., Ant. 1, 180s.—FBurkitt, The Syriac Forms of NT Proper Names 1912, 82; Billerbeck IV 252s., 452ss.), Melquisedeque, rei de Salém e sacerdote do Deus Altíssimo na época de Abraão (ambas as caracterizações conforme Gen 14:18). Na tipologia de Hb, figura de Cristo como sumo sacerdote (Mel. não é chamado <span class=\"greek\">ἀρχιερεύς</span> na LXX, em Philo nem em Joseph., mas <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">ἱερεύς</span> em Philo, Abr. 235) 5:6, 10; 6:20; 7:1, 10s., 15, 17 (quase sempre Ps 109:4b influenciou essas passagens, quando não é citado integralmente: <span class=\"greek\">σὺ</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">ἱερεὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τάξιν</span> <span class=\"greek\">Μελχισέδεκ</span>).—Sobre Mel. no NT: FrJJérome, D. gesch. M-Bild u. s. Bed. im Hb., diss. Freib. 1920; GWuttke, M., der Priesterkönig von Salem: E. Studie zur Gesch. der Exegese 1927; RGyllenberg, Kristusbilden i Hebréer brevet 1928; GBardy, M. dans la trad. patrist.: RB 35, 1926, 496–509; 36, 1927, 25–45; HStork, D. sog. Melchisedekianer 1928; HWindisch, Hdb., exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:4</a> (2’31); EKäsemann, D. wandernde Gsvolk ’39; HdelMedico, ZAW 69, ’57, 160–70; JPetuchowski, HUCA 28, ’57, 127–36; JFitzmyer, CBQ 25, ’63, 305–21; MdeJonge e ASvd Woude, 11 Q Melch. and the NT, NTS 12, ’66, 301–26 (sobre essa passagem de Qumran, ver também AAschim, TTK 66, ’95, 85–103); SLyonnet, Sin, Redemption and Sacrifice, ’70, 310–12 (bibliografia).—M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέλω</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέλω</span>: ver <span class=\"greek\">μέλομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεμβράνα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεμβράνα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (empréstimo do latim: membrana; ver B-D-F §5, 1 [<span class=\"greek\">μεμβράνη</span>]; Rob. 109; GMeyer, D. lat. Lehnworte im Neugriech.: SBWienAk 132, 1895, 44 [<span class=\"greek\">μεμβρᾶνα</span>];—Charax de Pérgamo [séculos II/III d.C.]: 103 Fgm. 37 Jac.; Acta Barn. 6 p. 66 Tisch. <span class=\"greek\">τὰς</span> <span class=\"greek\">μεμβράνας</span>; POxy 2156, 9 [cerca de 400 d.C.]), pergaminho, utilizado na fabricação de livros ou para diversas finalidades de escrita. <span class=\"greek\">τὰ</span> <span class=\"greek\">βιβλία</span>, <span class=\"greek\">μάλιστα</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">μ</span>., os livros (mais precisamente, “obras escritas”, isto é, rolos, judaicos ou não, feitos de papiro ou peles de animais), sobretudo os pergaminhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:13</a> (em favor da interpretação “rolos”, cf. Theodoret 3, 695 Sch. <span class=\"greek\">μεμβράνας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">εἱλητὰ</span> <span class=\"greek\">κέκληκεν</span>· <span class=\"greek\">οὕτω</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">Ῥωμαῖοι</span> <span class=\"greek\">καλοῦσι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δέρματα</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">εἱλητοῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">εἶχον</span> <span class=\"greek\">πάλαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θείας</span> <span class=\"greek\">γραφάς</span>. <span class=\"greek\">οὕτω</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παρόντος</span> <span class=\"greek\">ἔχουσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἰουδαῖοι</span>, “ele chama os rolos de <span class=\"greek\">μεμβράνας</span>, pois os romanos aplicam esse termo às peles. Antigamente conservavam as Escrituras sagradas em rolos, e assim os judeus fazem até o presente”. Mas WHatch [carta de 12 de setembro de ’53] concluiu que as <span class=\"greek\">μεμβράνα</span> de 2 Ti eram códices de pergaminho, assinalando Martial, Ep. 14, 7; 184: pugillares membranei = “pergaminhos de tamanho suficiente para caber na mão”; cf. Ep. 14, 186; 188; 190; 192; MJames, Companion to Latin Studies3 ’43, 238. Assim também CMcCown, HTR 34, ’41, 234s.—RAC 2, 664ss. [bibliografia]; Kl. Pauly III 1185s. [bibliografia]).—B. 1289. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεμενήκεισαν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεμενήκεισαν</span>: ver <span class=\"greek\">μένω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέμιγμαι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέμιγμαι</span>: ver <span class=\"greek\">μίγνυμι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεμμίαμαι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεμμίαμαι</span>: ver <span class=\"greek\">μιαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέμνημαι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέμνημαι</span>: ver <span class=\"greek\">μιμνῄσκομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέμφομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέμφομαι</span>, futuro, 3ª pessoa do singular <span class=\"greek\">μέμψεται</span> Sir 41, 7; 1º aoristo <span class=\"greek\">ἐμεμψάμην</span> (cf. o verbete seguinte; Hes. e outros; inscrições, papiros, LXX; TestJob 42:2; Just.), censurar, repreender, achar defeito em, com acusativo <span class=\"greek\">τινά</span>, alguém (Hes. e outros; PFay 111, 3 [95/96 d.C.]; POxy 1481, 5; PRyl 239, 13; TestJob, Philo; Jos., Ant. 13, 109; SibOr 5, 237), e <span class=\"greek\">τὶ</span>, alguma coisa (Pind. e outros); ou com dativo <span class=\"greek\">τινί</span>, alguém (Aeschyl. e outros; Alex. Polyhistor [século I a.C.]: 273 Fgm. 46 Jac.; Jos., C. Ap. 1, 142; Sir 41:7; 2 Macc 2:7.—B-D-F §152, 1; Rob. 473; RSchekira, De imperatoris Marci Aurelii Ant. librorum <span class=\"greek\">τὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἑαυτόν</span> sermone, diss. Greifswald 1919, 147). <span class=\"greek\">μεμφόμενος</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">λέγει</span>, ele os censura ao dizer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:8</a> (variante textual <span class=\"greek\">αὐτοῖς</span>; JWolmarans, ZNW 75, ’84, 139–44). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">μέμψασθαι</span>, ele não terá nada de que nos censurar Hs 9, 10, 4; <span class=\"greek\">γνῶσιν</span> Dg 12:5. Em emprego absoluto (Sir 11:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:2</a>, variante textual; Hs 10, 3, 3 Lat. (=Ox 404 recto, Fgm. c, 13–15, duas vezes).—<span class=\"greek\">τί</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">μέμφεται</span>; (Aristippus em Diog. L. 2, 77: <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐμέμφου</span>; Ael. Aristid. 32 p. 604 D.: <span class=\"greek\">τί</span> <span class=\"greek\">μέμφονται</span>;), por que ele ainda encontra defeito? ou que defeito ainda pode encontrar? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:19</a> (Appian, Maced. 11 §5 <span class=\"greek\">εἴ</span> <span class=\"greek\">τι</span> <span class=\"greek\">μέμφονται</span> = se têm alguma censura a fazer.—Também é possível “queixar-se”, como em Jos., Ant. 2, 63; Ps.-Pla., Axioch. 7, 368a. Sobre o conteúdo, cf. Oenomaus em Eus., PE 6, 7, 36: <span class=\"greek\">ὁ</span> <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">οὗτος</span>, sob cujo controle se encontra tudo, <span class=\"greek\">τί</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">τίνυται</span> [punir]; … <span class=\"greek\">τί</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπειλεῖ</span> <span class=\"greek\">ἡμῖν</span>;).—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεμψίμοιρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεμψίμοιρος</span>, <span class=\"greek\">ον</span> (Isocr. 12, 8; Aristot., HA 608b, 10 [espúrio]; cf. Theophr., Char. 17 [22], 1 <span class=\"greek\">ἔστι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μεμψιμοιρία</span> <span class=\"greek\">ἐπιτίμησίς</span> <span class=\"greek\">τις</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">προσῆκον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δεδομένων</span>, “resmungar é uma espécie de reclamação desmedida acerca das circunstâncias que couberam a alguém”; Lucian, Cynic. 17, Tim. 55; Plut., De Ira Cohib. 13 p. 461b; Ptolem., Apotel. 3, 14, 23; Vett. Val. 17, 12), composto de <span class=\"greek\">μέμφομαι</span>, “censurar”, e <span class=\"greek\">μοῖρα</span>, “quinhão na vida, destino” = queixoso de sua sorte, descontente (com <span class=\"greek\">γογγυστής</span>) Jd 16, num comentário satírico a respeito de pessoas que escolhem um estilo de vida desviante e depois reclamam (com ironia?) de que esse é seu “destino infeliz”. Cf. o discurso de Edmundo em WShakespeare, Rei Lear, Ato 1, cena 2: “Eis a excelente tolice do mundo … fazemos o sol, a lua e as estrelas culpados de nossos desastres; como se fôssemos vilões por necessidade; tolos por compulsão celestial … e como se todo o mal que há em nós fosse imposto por uma força divina.”—DELG s.v. <span class=\"greek\">μέμφομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέμψις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέμψις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">μέμφομαι</span>; Aeschyl. e posteriores; BGU 926, 6; POxy 140, 16; 1255, 19; LXX; Philo; Jos., C. Ap. 2, 242, Vi. 266), motivo de queixa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:13</a> D.—DELG s.v. <span class=\"greek\">μέμφομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0230-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέν</h1><div class=\"entry-meta\"><span>partícula</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέν</span>, partícula afirmativa, forma enfraquecida de <span class=\"greek\">μήν</span> (Hom. e posteriores). Uma das partículas mais comuns em Hom., Hdt. e outros, mas seu emprego diminui acentuadamente em épocas posteriores. Ocorre apenas 180 vezes no NT. Em sete dessas passagens as edições divergem (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:25</a>; 16:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:15</a>; 12:20; em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:23</a> W-H. colocam o termo entre colchetes). Os manuscritos revelam variação ainda maior. Não ocorre em Rv, 2 Th, 1 Ti, Tit, Phlm, 2 Pt, 1, 2, 3J; Eph, Col, 1 Th, Js têm apenas uma ocorrência cada. É também bastante rara em 1, 2 Cl, Ign, GPt, mas comum em Ac, Hb, B e especialmente em Dg. Nunca inicia uma oração. Cf. Kühner-G. II p. 264ss.; Schwyzer II 569s.; Denniston 359–97; B-D-F §447; Rob. 1150–53; Mlt-Turner 331s.</p><p class=\"entry-text\">① Marcador de correlação com outras partículas.</p><p class=\"entry-text\">ⓐ Introduzindo uma oração concessiva, seguida de outra oração com partícula adversativa: é verdade que … mas, por um lado … por outro; contudo, em muitos casos uma tradução equivalente não se ajusta a esse esquema: deve-se enfatizar o contraste na segunda oração, frequentemente com mas.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">μὲν</span> … <span class=\"greek\">δέ</span>: <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">βαπτίζω</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐρχόμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">θερισμὸς</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐργάται</span> 9:37. <span class=\"greek\">τὸ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ποτήριόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">πίεσθε</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καθίσαι</span> 20:23. <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> … <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνθρώπῳ</span> <span class=\"greek\">ἐκείνῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:21</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πρώτου</span> <span class=\"greek\">κατέαξαν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σκέλη</span> … <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">ἐλθόντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:32</a> e frequentemente. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:24</a>; 11:14; 12:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:20</a>.—Com conjunções: <span class=\"greek\">εἰ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span>, se … mas se Dg 3:2 (TestJob 23:5; Ar. 13:7). <span class=\"greek\">εἰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span>, se, pois, … mas se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:38</a>; cf. 25:11. <span class=\"greek\">εἰ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">νῦν</span> <span class=\"greek\">δέ</span>, se … mas agora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:15</a>. <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">δέ</span>, de fato … mas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:24</a>; 20:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:4</a>; 12:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25</a>. <span class=\"greek\">μὲν</span> <span class=\"greek\">γὰρ</span> … <span class=\"greek\">δέ</span>/<span class=\"greek\">ἀλλά</span>, pois, de fato … mas (Wsd 7:30; Job 28:2; 2 Macc 6:4; 7:36; 4 Macc 9:8s., 31s.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:36</a>s.; 23:8; 28:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:3</a>; 11:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:1</a>–3; 11:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:18</a>, 20s.; 12:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:22</a> (em ordem inversa): também <span class=\"greek\">ἀλλά</span> em lugar de <span class=\"greek\">δέ</span> na apódose 4:16s. (como em 3 Macc 2:15s.), ver <span class=\"greek\">β</span>. <span class=\"greek\">κἂν</span> <span class=\"greek\">μὲν</span> … , <span class=\"greek\">εἰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μήγε</span>, se … mas se não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:9</a>. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὲν</span> … , <span class=\"greek\">ἐὰν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:13</a>. Com preposição, <span class=\"greek\">εἰς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:6</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἀλλά</span>, é verdade que … mas (Thu. 3, 2, 1; X., Oec. 3, 6; Tetr. Iamb. 1, 2, 3; TestJob 4:1; Ath. 16, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:12</a> (variante textual sem <span class=\"greek\">μέν</span>). <span class=\"greek\">πάντα</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">καθαρὰ</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">κακὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνθρώπῳ</span>, de fato tudo é puro, mas é mau para o homem … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:20</a>. <span class=\"greek\">σὺ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">καλῶς</span> … <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ὁ</span> <span class=\"greek\">ἕτερος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:17</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:16</a> (ver <span class=\"greek\">α</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">μὲν</span> … <span class=\"greek\">πλήν</span>, de fato … mas (Galen, Inst. Log. c. 8, 2 Kalbfl. [1896]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:22</a>.</p><p class=\"entry-text\">ⓑ Sem sentido propriamente concessivo em <span class=\"greek\">μέν</span>, mas com força adversativa em <span class=\"greek\">δέ</span>, de modo que <span class=\"greek\">μέν</span> não precisa ser traduzido: <span class=\"greek\">αὐτοὶ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:48</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:36</a>. <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:12</a>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἀπολλυμένοις</span> … <span class=\"greek\">τοῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">σῳζομένοις</span> v. 18. <span class=\"greek\">Ἰουδαίοις</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἔθνεσι</span> <span class=\"greek\">δέ</span> v. 23. <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:1</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:14</a>; Dg 2:8.</p><p class=\"entry-text\">ⓒ Por vezes, a combinação <span class=\"greek\">μὲν</span> … <span class=\"greek\">δέ</span> não enfatiza um contraste, mas separa uma ideia de outra numa série, distinguindo-as claramente: <span class=\"greek\">πρῶτον</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἔπειτα</span> <span class=\"greek\">δέ</span>, em primeiro lugar … em seguida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:2</a>. <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">δέ</span>, um … o outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:8</a>, 23 (cf. Lucian, Hermot. 66 <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἑπτά</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πέντε</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τριάκοντα</span>; Just., D. 35, 6; 39, 2; cf. TestAbr A 10 p. 87, 21 [Stone p. 22] <span class=\"greek\">ἄλλους</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἑτέρους</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:21</a>. <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">δέ</span>, um … o outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:35</a>; 25:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:21</a>; Jd 22. <span class=\"greek\">ἃ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἃ</span> <span class=\"greek\">δέ</span>, alguns … outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δέ</span>, um … o outro, mas, no plural, uns … outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:4</a>; 17:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:16</a>; Dg 2:2s. <span class=\"greek\">ἕκαστος</span> … , <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὕτως</span>, cada qual …, um de uma maneira, outro de outra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:7</a>. <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πιστεύει</span> <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">πάντα</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀσθενῶν</span>, um tem confiança para comer de tudo, mas aquele que é fraco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:2</a>. <span class=\"greek\">τινὲς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">τινὲς</span> <span class=\"greek\">δέ</span>, uns … outros, porém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:15</a>. <span class=\"greek\">ἄλλη</span> <span class=\"greek\">μὲν</span> …, <span class=\"greek\">ἄλλη</span> <span class=\"greek\">δὲ</span> …, <span class=\"greek\">ἄλλη</span> <span class=\"greek\">δέ</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:39</a>. <span class=\"greek\">ἑτέρα</span> <span class=\"greek\">μὲν</span> …, <span class=\"greek\">ἑτέρα</span> <span class=\"greek\">δέ</span> v. 40. <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> … , <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">δὲ</span> … , <span class=\"greek\">ἕτεροι</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:14</a>. <span class=\"greek\">ᾧ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">γὰρ</span> … , <span class=\"greek\">ἄλλῳ</span> <span class=\"greek\">δὲ</span> … , <span class=\"greek\">ἑτέρῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:8</a>ss. <span class=\"greek\">ἃ</span> <span class=\"greek\">μὲν</span> … , <span class=\"greek\">ἄλλα</span> <span class=\"greek\">δὲ</span> … , <span class=\"greek\">ἄλλα</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:4</a>ss. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">μὲν</span> … , <span class=\"greek\">τοῦτο</span> <span class=\"greek\">δέ</span>, em parte … em parte (Hdt. 3, 106; Isocr. 4, 21; 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:33</a> (<span class=\"greek\">μέν</span> seguido de mais de um <span class=\"greek\">δέ</span>: dois em Libanius, Or. 18, p. 251, 3s.; Or. 59 p. 240, 13; quatro em Or. 64 p. 469, 14).</p><p class=\"entry-text\">② Marcador de contraste ou continuação sem correlação expressa e, frequentemente, em anacolutos.</p><p class=\"entry-text\">ⓐ Quando o contraste pode ser suprido pelo contexto e, portanto, omitido por ser evidente: <span class=\"greek\">λόγον</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἔχοντα</span> <span class=\"greek\">σοφίας</span> (subentendendo-se <span class=\"greek\">ὄντα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἄλογα</span> ou algo semelhante), têm reputação de sábios (mas são insensatos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a> (interpretação diferente em BHollenbach, NTS 25, ’79, 254–61: oração subordinada inserida em sua oração principal). <span class=\"greek\">τὰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀποστόλου</span> <span class=\"greek\">κατειργάσθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, os sinais característicos de um verdadeiro apóstolo foram realizados entre vós (mas não lhes prestastes atenção) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:12</a>. <span class=\"greek\">ἤδη</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἥττημα</span>, de fato, já é uma derrota para vós (mas a tornais ainda pior) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:7</a>.—<span class=\"greek\">μέν</span> serve para enfatizar o sujeito em orações que apresentam uma declaração acerca do estado pessoal do falante, sobretudo intelectual ou emocional; assim, <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Παῦλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:18</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">εὐδοκία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐμῆς</span> <span class=\"greek\">καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:1</a>.</p><p class=\"entry-text\">ⓑ Às vezes, o contraste é efetivamente expresso, mas não em forma adversativa (Diod S 12, 70, 6 <span class=\"greek\">Ἀθηναῖοι</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐπιβουλεύσαντες</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Βοιωτοῖς</span> <span class=\"greek\">τοιαύτῃ</span> <span class=\"greek\">συμφορᾷ</span> <span class=\"greek\">περιέπεσον</span> = assim, vê-se que os atenienses, depois de conspirarem contra os beócios, sofreram tal reviravolta em sua sorte; Polyaenus, com efeito dramático: 4, 3, 20 <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> … , <span class=\"greek\">Ἀλέξανδρος</span> … ; 2, 3, 2): <span class=\"greek\">τότε</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἔπειτα</span> (aqui seria esperado <span class=\"greek\">δέ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:6</a>s. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">ἀπόστολος</span>, na medida, pois, em que sou apóstolo dos gentios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:13</a> (o contraste segue no v. 14); cf. 7:12 e 13ss.</p><p class=\"entry-text\">ⓒ Observa-se anacoluto nas enumerações, quando são interrompidas ou prosseguem de modo formalmente irregular: <span class=\"greek\">πρῶτον</span> <span class=\"greek\">μέν</span>, em primeiro lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:8</a>; 3:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:18</a>. <span class=\"greek\">πρῶτον</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἔπειτα</span> (X., Cyr. 7, 5, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:17</a>. No prólogo de Ac (ver <span class=\"greek\">λόγος</span> 1b), a oração com <span class=\"greek\">δέ</span> correspondente a <span class=\"greek\">τὸν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">λόγον</span> 1:1 (Diod S 11, 1, 1 <span class=\"greek\">῾Η</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">ταύτης</span> <span class=\"greek\">βίβλος</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔσχε</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πράξεων</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">δέ</span> …, “O livro precedente … continha … ; neste, por sua vez …”) pode ter sido omitida no trabalho editorial, segundo Norden, Agn. Th. 311ss.; 397.</p><p class=\"entry-text\">ⓓ <span class=\"greek\">μέν</span> seguido de <span class=\"greek\">καί</span> não é usual (Ael. Aristid. 31, 19 K.=11 p. 133 D.; IAsMinSW 325, 10ss. <span class=\"greek\">μὲν</span> … <span class=\"greek\">καί</span>; POxy 1153, 14 [século I d.C.], duas braçadeiras <span class=\"greek\">ἓν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">σανδύκινον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">πορφυροῦν</span>; TestJob 40:7s.; ApcMos 15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:4</a>ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a>ss.; MPol 2:4.</p><p class=\"entry-text\">ⓔ <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> indica continuação (TestJob 40:14; Just., A I, 7, 3; ver B-D-F §451, 1; Kühner-G. II 157s., mas observar a ressalva de Denniston, p. 473, n. 1; Mayser II/3, 152s.; Rob. 1151; 1191): assim, então <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:18</a>. Especialmente em Ac: 1:6, 18; 2:41; 5:41; 8:25; 9:31; 11:19; 13:4; 14:3 (DSharp, ET 44, ’33, 528); 15:3, 30; 16:5; 17:12, 17, 30; 19:32; 23:18, 22, 31; 25:4; 26:4, 9; 28:5. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:4</a> (B-D-F §450, 4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:1</a>; Papias (2:16). <span class=\"greek\">εἰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span>, ora, se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a>; 8:4.</p><p class=\"entry-text\">ⓕ <span class=\"greek\">μενοῦν</span>, <span class=\"greek\">οὐμενοῦν</span> e <span class=\"greek\">μενοῦνγε</span>: ver os verbetes correspondentes.—JLee, Some Features of the Speech of Jesus in Mark’s Gospel: NovT 27, ’85, 1–26.—DELG s.v. 1 <span class=\"greek\">μήν</span>. M-M.</p></section></article>"};
